import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // quote
  it.todo("quote with empty item list -> premium 5 G (only the processing fee)");
  it.todo("newcomer quotes a plain sword -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("newcomer quotes a plain amulet -> premium 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("newcomer quotes a plain staff -> premium 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("newcomer quotes a plain potion -> premium 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("2 runes -> 50 G base premium -> premium 60 G");
  it.todo("3 runes -> 60 G block base premium -> premium 71 G");
  it.todo("4 runes -> 100 G base premium, no block (block requires exactly 3) -> premium 115 G");
  it.todo("7 runes -> 175 G base premium, 197.5 G rounded up in MHPCO's favor -> premium 198 G");
  it.todo("2 runes + 1 moonstone -> 75 G base premium, no block (different types) -> premium 88 G (87.5 rounded up)");
  it.todo("3 runes + 3 moonstones -> 120 G base premium (two separate blocks) -> premium 137 G");
  it.todo("newcomer with a cursed sword (steel, enchantment 3) -> premium 165 G");
  it.todo("cursed sword + plain amulet -> curse adds 50 G of the sword's base only (210 G) -> premium 231 G");
  it.todo("sword with exactly enchantment 5 -> high-enchantment surcharge applies -> premium 145 G");
  it.todo("customer with exactly 2 years with MHPCO quotes a plain sword -> loyalty discount applies -> premium 95 G");
  it.todo("second quote in the scenario gets 15 % follow-up discount -> plain sword premiums 115 G then 100 G");
  it.todo("quote with an unknown item type (broomstick) -> scenario is rejected with an Error");

  // claim
  it.todo("regular sword (steel, enchantment 3), damage 500 G -> payout 400 G, remaining cap 1600 G");
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible)");
  it.todo("payout yielding 350.5 G (steel sword enchantment 9, damage 901 G) -> payout 350 G (rounded down)");
  it.todo("dragon attack damages sword (500 G) and amulet (300 G) -> payout 600 G (deductible per item), remaining cap 2600 G");
  it.todo("sword insured, two successive claims of 1500 G -> payouts 1400 G / 600 G, remaining caps 600 G / 0 G");
  it.todo("claim references the policy by zero-based quote step index -> amulet of policy 1 damaged 300 G -> payout 200 G, remaining cap 1000 G");
  it.todo("claim damages an amulet when only a sword is insured -> scenario is rejected with an Error");
  it.todo("claim with damage amount -200 -> scenario is rejected with an Error");
  it.todo("two sword damages but only one sword insured -> whole claim is rejected with an Error");

  // CLI
  it.todo("CLI reads the scenario from stdin and writes {results} JSON to stdout with exit code 0 (schema example: premium 59 G, payout 100 G, remaining cap 1100 G)");
  it.todo("CLI with an unknown quote item type -> non-zero exit code, error description on stderr, nothing on stdout");

  describe("verification", () => {
    it.todo("sword with enchantment 4 -> no high-enchantment surcharge -> premium 115 G");
    it.todo("cursed sword with enchantment 4 -> only curse surcharge -> premium 165 G");
    it.todo("cursed sword with exactly enchantment 5 -> both surcharges -> premium 195 G");
    it.todo("cursed amulet -> curse applies to the amulet's base premium -> premium 101 G");
    it.todo("staff with enchantment 6 -> high-enchantment surcharge on staff base -> premium 117 G");
    it.todo("3 moonstones -> 60 G block base premium -> premium 71 G");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount -> plain sword premium 115 G");
    it.todo("long-standing customer's second contract: 3 years, second quote, cursed sword enchantment 7 -> premium 160 G");
    it.todo("third quote in the scenario also gets the follow-up discount -> plain sword premium 100 G");
    it.todo("damage to a rune 200 G -> payout 100 G, remaining cap 400 G");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G -> payout 400 G");
    it.todo("sword + amulet, cap 3200 G: damages 2000 G and 1500 G -> payout 3200 G (capped), remaining cap 0 G");
    it.todo("cursed sword cap is 2000 G (unmodified insurance value): damage 3000 G -> payout 2000 G, remaining cap 0 G");
    it.todo("sword + 3 runes insurance sum 1750 G, cap 3500 G: sword damage 3000 G -> payout 2900 G, remaining cap 600 G");
    it.todo("two swords insured (cap 4000 G), both damaged 500 G -> payout 800 G, remaining cap 3200 G");
    it.todo("two swords insured (cap 4000 G), one sword damaged 5000 G -> payout 4000 G, remaining cap 0 G");
    it.todo("claim damages an item with an unknown type -> scenario is rejected with an Error");
    it.todo("CLI with a claim referencing an item not in the policy -> non-zero exit code, error description on stderr");
    it.todo("CLI with a claim damage amount -200 -> non-zero exit code, error description on stderr");
  });
});

