import { percentOf } from "./percent.js";
import { type Item, isComponent, mainItemPrices } from "./items.js";

const DEDUCTIBLE_PER_DAMAGE = 100;
const CAP_MULTIPLIER = 2;
const HIGH_ENCHANTMENT_CLAUSE_LEVEL = 8;
const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
const FULL_REIMBURSEMENT_PERCENT = 100;
const COMPONENT_INSURANCE_VALUE = 250;


export interface Damage {
  itemType: string;
  amount: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

const insuranceValue = (item: Item): number =>
  isComponent(item) ? COMPONENT_INSURANCE_VALUE : mainItemPrices(item).insuranceValue;

const insuranceSum = (items: Item[]): number => items.reduce((sum, item) => sum + insuranceValue(item), 0);

const fallsUnderHighEnchantmentClause = (item: Item | undefined): boolean =>
  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAUSE_LEVEL;

function reimbursementPercent(damagedItem: Item | undefined): number {
  return fallsUnderHighEnchantmentClause(damagedItem) ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT : FULL_REIMBURSEMENT_PERCENT;
}

function damagePayout(damage: Damage, insuredItems: Item[]): number {
  const damagedItem = insuredItems.find((item) => item.type === damage.itemType);
  return percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE_PER_DAMAGE;
}

const roundPayoutInMHPCOFavor = Math.floor;

export function processClaim(insuredItems: Item[], damages: Damage[]): ClaimResult {
  const cap = CAP_MULTIPLIER * insuranceSum(insuredItems);
  const payout = roundPayoutInMHPCOFavor(damages.reduce((sum, damage) => sum + damagePayout(damage, insuredItems), 0));
  return { payout, remainingCap: cap - payout };
}

